using System.Text;
using Eternal.Core.Engine;
using Eternal.Core.Logging;
using Eternal.Core.Persistence;
using Eternal.Core.Platform;

namespace Eternal.Core.Mods;

public sealed record ModItem(
    string Name,
    string DisplayName,
    ModKind Kind,
    string Type,
    string Description,
    int FileCount,
    bool Enabled,
    int Priority,
    IReadOnlyList<string> Particles,
    IReadOnlyList<ModOverlap> Wins,
    IReadOnlyList<ModOverlap> Loses,
    IReadOnlyList<CompatIssue> Issues,
    string? Thumbnail,
    bool CustomThumbnail,
    string? Source)
{
    /// <summary>Generated by the launcher and switched from its own page, never from the mod list.</summary>
    public bool Managed => Kind == ModKind.Addon && Name == Sounds.CustomSoundMod.Folder;
}

public sealed record ImportProgress(string Message, double Fraction);

public sealed record ImportOutcome(IReadOnlyList<ImportItemResult> Items, IReadOnlyList<string> Failures)
{
    public int Imported => Items.Sum(i => i.Mods.Count(m => m.IsNew)) + Items.Sum(i => i.Mods.Count(m => !m.IsNew));
    public bool AnyChanged => Items.Any(i => i.Mods.Count > 0);
}

public sealed class ModLibrary
{
    private readonly PreloaderEngine _engine;
    private readonly AppPaths _paths;
    private readonly ThumbnailStore _thumbnails;
    private readonly Func<string?> _tfPath;
    private readonly object _gate = new();
    private IReadOnlyList<LibraryMod> _library = [];
    private IReadOnlyList<ModOverlap> _overlaps = [];
    private IReadOnlyList<CompatIssue> _issues = [];
    private CancellationTokenSource? _analysis;

    public ModLibrary(PreloaderEngine engine, AppPaths paths, ThumbnailStore thumbnails, Func<string?>? tfPath = null)
    {
        _engine = engine;
        _paths = paths;
        _thumbnails = thumbnails;
        _tfPath = tfPath ?? (() => null);
        State = JsonFile.Load(paths.ModStateFile, ModJson.Default.ModState, () => new ModState(), out var outcome);
        LoadOutcome = outcome;
    }

    public ModState State { get; }
    public LoadOutcome LoadOutcome { get; }
    public bool Loaded { get; private set; }
    public IReadOnlyList<ModItem> Items { get; private set; } = [];

    public event Action? Changed;

    public event Action? DesiredChanged;

    public ThumbnailStore Thumbnails => _thumbnails;

    public DesiredPreload? Desired()
    {
        if (!Loaded)
            return null;
        lock (_gate)
        {
            var enabled = State.Order.Where(e => e.Enabled && _library.Any(l => l.Name == e.Name && l.Kind == e.Kind)).ToList();
            return new DesiredPreload(
                enabled.Where(e => e.Kind == ModKind.Addon).Select(e => e.Name).ToArray(),
                enabled.Where(e => e.Kind == ModKind.Particle).Select(e => e.Name).ToArray(),
                State.Options,
                Signature(enabled));
        }
    }

    private string Signature(IEnumerable<ModEntry> enabled)
    {
        var sb = new StringBuilder();
        foreach (var entry in enabled)
        {
            var mod = _library.FirstOrDefault(l => l.Name == entry.Name && l.Kind == entry.Kind);
            sb.Append(entry.Name).Append('|').Append(mod?.FileCount).Append('|').Append(mod?.Modified).Append('\n');
        }
        return sb.ToString();
    }

    public async Task<bool> RefreshAsync(CancellationToken cancellation = default)
    {
        var library = await _engine.LibraryAsync(cancellation).ConfigureAwait(false);
        if (library is null)
            return false;

        var before = Desired();
        lock (_gate)
        {
            _library = library;
            foreach (var mod in library.Where(m => !State.Order.Any(e => e.Name == m.Name && e.Kind == m.Kind)))
            {
                var entry = new ModEntry { Name = mod.Name, Kind = mod.Kind, Enabled = false };
                if (IsManaged(entry))
                    State.Order.Insert(0, entry);
                else
                    State.Order.Add(entry);
            }
            State.Order.RemoveAll(e => !library.Any(m => m.Name == e.Name && m.Kind == e.Kind));
        }
        Loaded = true;
        SaveState();
        Rebuild();
        Log.Info($"Mod library: {Items.Count} mods, {Items.Count(i => i.Enabled)} enabled");
        if (!Same(before, Desired()))
            DesiredChanged?.Invoke();
        ScheduleAnalysis();
        return true;
    }

    private static bool Same(DesiredPreload? a, DesiredPreload? b) =>
        a is not null && b is not null
        && a.Addons.SequenceEqual(b.Addons) && a.Particles.SequenceEqual(b.Particles)
        && a.Options.ToEngine() == b.Options.ToEngine() && a.LibrarySignature == b.LibrarySignature;

    public async Task<ImportPlan> PrepareAsync(string path, IProgress<ImportProgress>? progress, CancellationToken cancellation = default)
    {
        var name = Path.GetFileName(path);
        string? staging = null;
        var target = path;
        try
        {
            if (ArchiveIngest.IsArchive(path))
            {
                var unpacking = new InlineProgress<double>(f => progress?.Report(new ImportProgress($"Unpacking {name}…", f * 0.3)));
                progress?.Report(new ImportProgress($"Unpacking {name}…", 0));
                target = await Task.Run(() => ArchiveIngest.Extract(path, _paths.ImportStagingDir, unpacking, cancellation), cancellation).ConfigureAwait(false);
                staging = Path.GetDirectoryName(target);
            }
            progress?.Report(new ImportProgress($"Looking inside {name}…", 0.3));
            var (inspection, problem) = await _engine.InspectAsync(target, _tfPath(), cancellation).ConfigureAwait(false);
            if (inspection is null)
                throw new ArchiveException(problem ?? $"{name} couldn't be read.");
            return new ImportPlan(path, target, staging, inspection);
        }
        catch
        {
            if (staging is not null)
                ArchiveIngest.TryDelete(staging);
            throw;
        }
    }

    public async Task<ImportOutcome> ImportAsync(ImportPlan plan, IReadOnlyCollection<string>? parts, IProgress<ImportProgress>? progress,
        string? name = null, CancellationToken cancellation = default)
    {
        name = name is not null && plan.Parts.Count == 1 ? ArchiveIngest.SafeFolderName(name) : null;
        var engineProgress = new InlineProgress<EngineProgress>(p => progress?.Report(new ImportProgress(p.Message, 0.4 + p.Percent / 100.0 * 0.6)));
        var (result, items) = await _engine.ImportAsync(plan.Unpacked ? [] : [plan.Path], plan.Unpacked ? [plan.Path] : [],
            engineProgress, parts, _tfPath(), name, cancellation).ConfigureAwait(false);
        var failures = items.Where(i => !i.Ok).Select(i => $"{i.Source}: {i.Message}").ToList();
        if (items.Count == 0 && !result.Success)
            failures.Add(result.ErrorSummary);

        var imported = items.SelectMany(i => i.Mods).ToList();
        await RefreshAsync(cancellation).ConfigureAwait(false);
        if (imported.Count > 0)
        {
            lock (_gate)
            {
                foreach (var mod in imported.Where(m => m.IsNew).Reverse())
                {
                    State.Order.RemoveAll(e => e.Name == mod.Name && e.Kind == mod.Kind);
                    State.Order.Insert(0, new ModEntry { Name = mod.Name, Kind = mod.Kind, Enabled = true });
                }
            }
            SaveState();
            Rebuild();
            DesiredChanged?.Invoke();
            ScheduleAnalysis();
        }
        return new ImportOutcome(items, failures);
    }

    private static bool IsManaged(ModEntry entry) => entry.Kind == ModKind.Addon && entry.Name == Sounds.CustomSoundMod.Folder;

    public void SetEnabled(string name, ModKind kind, bool enabled)
    {
        lock (_gate)
        {
            var entry = State.Order.FirstOrDefault(e => e.Name == name && e.Kind == kind);
            if (entry is null || entry.Enabled == enabled || IsManaged(entry))
                return;
            entry.Enabled = enabled;
        }
        Commit();
    }

    /// <summary>Picks up the regenerated hit and kill sounds mod and switches it to what its own page says.</summary>
    public async Task SyncManagedAsync(bool enabled)
    {
        await RefreshAsync().ConfigureAwait(false);
        lock (_gate)
        {
            if (State.Order.FirstOrDefault(IsManaged) is not { } entry || entry.Enabled == enabled)
                return;
            entry.Enabled = enabled;
        }
        Commit();
    }

    public void Move(string name, ModKind kind, int index)
    {
        lock (_gate)
        {
            var entry = State.Order.FirstOrDefault(e => e.Name == name && e.Kind == kind);
            if (entry is null)
                return;
            State.Order.Remove(entry);
            State.Order.Insert(Math.Clamp(index, 0, State.Order.Count), entry);
        }
        Commit();
    }

    /// <summary>The hit and kill sounds mod follows its own page, except when <paramref name="includeManaged"/> turns everything off for Restore vanilla.</summary>
    public void SetAllEnabled(bool enabled, bool includeManaged = false)
    {
        lock (_gate)
        {
            foreach (var entry in State.Order.Where(e => includeManaged || !IsManaged(e)))
                entry.Enabled = enabled;
        }
        Commit();
    }

    public IReadOnlyList<string> ApplySelection(Profiles.ProfileMods mods)
    {
        List<string> missing;
        lock (_gate)
        {
            var wanted = mods.Addons.Select(a => (Name: a, Kind: ModKind.Addon)).Concat(mods.Particles.Select(p => (Name: p, Kind: ModKind.Particle))).ToList();
            var found = wanted.Select(w => (w.Name, Entry: Resolve(w.Name, w.Kind, mods.Sources?.GetValueOrDefault(w.Name)))).ToList();
            missing = found.Where(f => f.Entry is null).Select(f => f.Name).ToList();
            var ordered = found.Select(f => f.Entry).OfType<ModEntry>().Distinct().ToList();
            foreach (var entry in State.Order.Where(e => !IsManaged(e)))
                entry.Enabled = ordered.Contains(entry);
            State.Order.RemoveAll(ordered.Contains);
            State.Order.InsertRange(0, ordered);
        }
        Commit();
        return missing;
    }

    private ModEntry? Resolve(string name, ModKind kind, string? source)
    {
        var ofKind = State.Order.Where(e => e.Kind == kind).ToList();
        if (source is not null)
        {
            var submission = source[..(source.LastIndexOf(':') + 1)];
            var bySource = ofKind.FirstOrDefault(e => e.Source == source)
                ?? ofKind.FirstOrDefault(e => e.Source?.StartsWith(submission, StringComparison.Ordinal) == true);
            if (bySource is not null)
                return bySource;
        }
        return ofKind.FirstOrDefault(e => e.Name == name);
    }

    public bool Has(string name, ModKind kind, string? source)
    {
        lock (_gate)
            return Resolve(name, kind, source) is not null;
    }

    public Dictionary<string, string> EnabledSources()
    {
        lock (_gate)
            return State.Order.Where(e => e.Enabled && !IsManaged(e) && Profiles.ProfileMods.IsShareableSource(e.Source))
                .GroupBy(e => e.Name).ToDictionary(g => g.Key, g => g.First().Source!, StringComparer.Ordinal);
    }

    public void SetOptions(ModBuildOptions options)
    {
        lock (_gate)
            State.Options = options;
        Commit();
    }

    public async Task<EngineResult> RemoveAsync(IReadOnlyList<ModItem> mods)
    {
        var result = await _engine.RemoveAsync(mods.Select(m => (m.Name, m.Kind))).ConfigureAwait(false);
        await RefreshAsync().ConfigureAwait(false);
        foreach (var name in mods.Select(m => m.Name).Distinct().Where(name => Items.All(i => i.Name != name)))
            _thumbnails.Delete(name);
        return result;
    }

    public void AdoptLegacyOrder(IReadOnlyList<string> enabledAddons)
    {
        lock (_gate)
        {
            for (var i = enabledAddons.Count - 1; i >= 0; i--)
            {
                var entry = State.Order.FirstOrDefault(e => e.Name == enabledAddons[i] && e.Kind == ModKind.Addon);
                if (entry is null)
                    continue;
                entry.Enabled = true;
                State.Order.Remove(entry);
                State.Order.Insert(0, entry);
            }
        }
        Commit();
    }

    public void ThumbnailChanged() => Rebuild();

    public string FreeName(string name, string submission)
    {
        lock (_gate)
            return FreeName(State.Order.ToList(), ArchiveIngest.SafeFolderName(name), submission);
    }

    internal static string FreeName(IEnumerable<ModEntry> order, string name, string submission)
    {
        var taken = order.Where(e => e.Source?.StartsWith(submission, StringComparison.Ordinal) != true)
            .Select(e => e.Name).ToHashSet(StringComparer.OrdinalIgnoreCase);
        var free = name;
        for (var n = 2; taken.Contains(free); n++)
            free = $"{name} {n}";
        return free;
    }

    public void SetSource(IEnumerable<string> names, string source)
    {
        var set = names.ToHashSet(StringComparer.Ordinal);
        lock (_gate)
        {
            foreach (var entry in State.Order.Where(e => set.Contains(e.Name)))
                entry.Source = source;
        }
        SaveState();
        Rebuild();
    }

    private void Commit()
    {
        SaveState();
        Rebuild();
        DesiredChanged?.Invoke();
        ScheduleAnalysis();
    }

    private void SaveState()
    {
        if (!LoadOutcome.CanSave)
            return;
        try
        {
            lock (_gate)
                JsonFile.Save(_paths.ModStateFile, State, ModJson.Default.ModState);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            Log.Warn($"Couldn't save the mod list: {ex.Message}");
        }
    }

    private void Rebuild()
    {
        lock (_gate)
        {
            var items = new List<ModItem>();
            var priority = 0;
            foreach (var entry in State.Order)
            {
                var mod = _library.FirstOrDefault(l => l.Name == entry.Name && l.Kind == entry.Kind);
                if (mod is null)
                    continue;
                var custom = _thumbnails.Find(mod.Name);
                items.Add(new ModItem(
                    mod.Name, mod.DisplayName, mod.Kind, mod.Type, mod.Description, mod.FileCount, entry.Enabled,
                    entry.Enabled ? priority++ : -1,
                    mod.Particles,
                    entry.Enabled ? _overlaps.Where(o => o.Winner == mod.Name).ToArray() : [],
                    entry.Enabled ? _overlaps.Where(o => o.Loser == mod.Name).ToArray() : [],
                    _issues.Where(i => i.Addon == mod.Name).ToArray(),
                    custom ?? _thumbnails.FindForSource(entry.Source),
                    custom is not null,
                    entry.Source));
            }
            Items = items;
        }
        Changed?.Invoke();
    }

    private void ScheduleAnalysis()
    {
        CancellationTokenSource cts;
        lock (_gate)
        {
            _analysis?.Cancel();
            _analysis = cts = new CancellationTokenSource();
        }
        _ = Task.Run(async () =>
        {
            try
            {
                await Task.Delay(400, cts.Token).ConfigureAwait(false);
                var desired = Desired();
                if (desired is null)
                    return;
                var (addonOverlaps, particleOverlaps) = await _engine.ConflictsAsync(desired.Addons, desired.Particles, cts.Token).ConfigureAwait(false);
                var issues = await _engine.CompatAsync(desired.Addons, cts.Token).ConfigureAwait(false);
                if (cts.IsCancellationRequested)
                    return;
                lock (_gate)
                {
                    _overlaps = [.. addonOverlaps, .. particleOverlaps];
                    _issues = issues;
                }
                Rebuild();
            }
            catch (OperationCanceledException)
            {
            }
            catch (Exception ex)
            {
                Log.Warn($"Mod analysis failed: {ex.Message}");
            }
        });
    }
}
